import React, { useState } from 'react';
import FileDropzone from '../common/FileDropzone';
import { ocrService } from '../../services/ocrService';
import { aiService } from '../../services/aiService';
import { jsPDF } from 'jspdf';
import { Sparkles, Loader2, BrainCircuit, Quote, Download, Settings, FileText } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { downloadFile } from '../../utils/download';
import JSZip from 'jszip';
import clsx from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs) {
  return twMerge(clsx(inputs));
}

export default function AISummarizer() {
  const [files, setFiles] = useState([]);
  const [summary, setSummary] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState('');

  const downloadSummary = () => {
    downloadFile(summary, `summary-${files[0].name.split('.')[0]}.txt`, 'text/plain');
  };

  const downloadSummaryAsPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text('AI Executive Summary', 15, 20);
    doc.setFontSize(11);
    const splitText = doc.splitTextToSize(summary, 180);
    doc.text(splitText, 15, 35);
    doc.save(`Summary-${files[0].name.split('.')[0]}.pdf`);
  };

  const handleSummarize = async () => {
    if (files.length === 0) return;

    setIsProcessing(true);
    setSummary('');
    try {
      if (files.length === 1) {
        const file = files[0];
        setProgress('Extracting text from PDF...');
        const text = await ocrService.extractTextFromPDF(file);

        if (!text.trim()) {
          throw new Error('No text found in PDF. Try using OCR first.');
        }

        setProgress('Analyzing with AI (this may take a minute)...');
        const aiSummary = await aiService.summarize(text);
        setSummary(aiSummary);
        downloadFile(aiSummary, `Summary-${files[0].name.split('.')[0]}.txt`, 'text/plain');
      } else {
        const zip = new (JSZip.default || JSZip)();
        for (const file of files) {
          setProgress(`Processing: ${file.name}...`);
          const text = await ocrService.extractTextFromPDF(file);
          if (!text.trim()) continue;

          const aiSummary = await aiService.summarize(text);
          zip.file(`Summary-${file.name.split('.')[0]}.txt`, aiSummary);
        }
        const content = await zip.generateAsync({ type: 'blob' });
        downloadFile(content, 'Summaries-Batch.zip', 'application/zip');
        setSummary('Batch summarization complete! Check your downloads.');
      }
    } catch (error) {
      console.error('Summarization failed:', error);
      const errorMsg = error.message || 'Failed to summarize PDF.';
      alert(errorMsg);
    } finally {
      setIsProcessing(false);
      setProgress('');
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 items-start justify-center w-full max-w-6xl">
      <div className="flex-1 w-full">
        <FileDropzone 
          files={files} 
          setFiles={setFiles} 
          multiple={true}
          accept={{ 'application/pdf': ['.pdf'] }} 
        />
      </div>

      <div className="w-full lg:w-72 glass-card p-6 space-y-6 animate-in fade-in slide-in-from-right-4">
        <div className="flex items-center justify-between">
          <h3 className="font-black text-lg text-slate-800 dark:text-zinc-100 flex items-center gap-2">
            <Settings className="text-accent" size={18} />
            SETTINGS
          </h3>
          {files.length > 2 && (
            <span className="bg-yellow-100 text-yellow-700 text-[8px] px-2 py-0.5 rounded-full font-black">
              BATCH
            </span>
          )}
        </div>

        <div className="space-y-3">
          <p className="text-[11px] text-slate-400 dark:text-zinc-400 font-medium leading-relaxed uppercase tracking-wider">
            {files.length > 1 
              ? `AI will analyze ${files.length} PDFs.`
              : 'Our AI will generate a concise summary.'}
          </p>
        </div>

        <button
          onClick={handleSummarize}
          disabled={files.length === 0 || isProcessing}
          className={cn(
            "w-full bg-accent hover:opacity-90 text-slate-900 py-4 rounded-2xl flex items-center justify-center gap-2 text-sm mt-4 font-black shadow-lg shadow-accent/10 transition-all",
            (files.length === 0 || isProcessing) && "opacity-50 cursor-not-allowed grayscale"
          )}
        >
          {isProcessing ? <Loader2 className="animate-spin" size={18} /> : <BrainCircuit size={18} />}
          {isProcessing ? 'THINKING...' : 'SUMMARIZE PDF'}
        </button>

        {progress && (
          <p className="text-[10px] text-accent font-black text-center animate-pulse uppercase tracking-widest">
            {progress}
          </p>
        )}
      </div>

      <AnimatePresence>
        {summary && (
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="mt-12 w-full max-w-4xl glass-card p-10 relative overflow-hidden"
          >
            <div className="absolute top-0 right-0 p-8 text-indigo-100 -rotate-12">
              <Quote size={80} />
            </div>

            <div className="relative z-10">
              <div className="flex items-center gap-3 mb-8">
                <div className="w-10 h-10 bg-accent text-slate-900 rounded-xl flex items-center justify-center">
                  <Sparkles size={20} />
                </div>
                <h4 className="text-xl font-bold text-slate-800 tracking-tight">AI Executive Summary</h4>
              </div>

              <div className="text-slate-700 dark:text-zinc-300 leading-relaxed text-lg font-medium italic">
                "{summary}"
              </div>

              <div className="mt-10 pt-8 border-t border-indigo-100 flex justify-between items-center text-sm">
                <div className="flex gap-2 items-center">
                  <span className="text-slate-400 dark:text-zinc-300 mr-2">Download:</span>
                  <button 
                    onClick={downloadSummary}
                    className="flex items-center gap-1.5 text-[10px] font-black text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-500/10 px-3 py-1.5 rounded-lg transition-all"
                  >
                    <Download size={14} /> TXT
                  </button>
                  <button 
                    onClick={downloadSummaryAsPDF}
                    className="flex items-center gap-1.5 text-[10px] font-black text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-500/10 px-3 py-1.5 rounded-lg transition-all"
                  >
                    <FileText size={14} /> PDF
                  </button>
                </div>
                <button 
                  onClick={() => setSummary('')}
                  className="text-slate-500 font-medium hover:underline"
                >
                  Summarize Another
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useState } from 'react';
import FileDropzone from '../common/FileDropzone';
import { pdfService } from '../../services/pdfService';
import { Zap, Download, Loader2, CheckCircle2, Settings } from 'lucide-react';
import { downloadFile } from '../../utils/download';
import JSZip from 'jszip';
import clsx from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs) {
  return twMerge(clsx(inputs));
}

export default function CompressPDF() {
  const [files, setFiles] = useState([]);
  const [level, setLevel] = useState('recommended'); // 'extreme', 'recommended', 'less'
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDone, setIsDone] = useState(false);

  const handleCompress = async () => {
    if (files.length === 0) return;

    setIsProcessing(true);
    try {
        if (files.length === 1) {
        const compressedBytes = await pdfService.compressPDF(files[0], level);
        downloadFile(compressedBytes, `compressed-${files[0].name}`);
      } else {
        const zip = new (JSZip.default || JSZip)();
        for (const file of files) {
          const compressedBytes = await pdfService.compressPDF(file, level);
          zip.file(`compressed-${file.name}`, compressedBytes);
        }
        const content = await zip.generateAsync({ type: 'blob' });
        downloadFile(content, 'Compressed-Batch.zip', 'application/zip');
      }
      setIsDone(true);
      setTimeout(() => setIsDone(false), 3000);
    } catch (error) {
      console.error('Compression failed:', error);
      alert('Failed to compress PDF.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 items-start justify-center w-full max-w-5xl">
      <div className="flex-1 w-full">
        <FileDropzone files={files} setFiles={setFiles} multiple={true} />
      </div>

      <div className="w-full lg:w-72 glass-card p-6 space-y-6 animate-in fade-in slide-in-from-right-4">
        <h3 className="font-black text-lg text-slate-800 dark:text-zinc-100 flex items-center gap-2">
          <Settings className="text-accent" size={18} />
          SETTINGS
        </h3>

        <div className="space-y-4">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Compression Level</label>
          <div className="space-y-2">
            {[
              { id: 'extreme', title: 'Extreme', desc: 'Lower quality' },
              { id: 'recommended', title: 'Recommended', desc: 'Good balance' },
              { id: 'less', title: 'Minimal', desc: 'High quality' }
            ].map(opt => (
              <button
                key={opt.id}
                onClick={() => setLevel(opt.id)}
                className={cn(
                  "w-full p-3 rounded-xl border-2 transition-all text-left",
                  level === opt.id ? "border-accent bg-accent/5" : "border-slate-50 dark:border-zinc-800 hover:bg-slate-50 dark:hover:bg-zinc-800"
                )}
              >
                <p className={cn("font-black text-xs", level === opt.id ? "text-slate-900 dark:text-zinc-100" : "text-slate-700 dark:text-zinc-300")}>{opt.title}</p>
                <p className="text-[10px] text-slate-400 font-medium">{opt.desc}</p>
              </button>
            ))}
          </div>
        </div>

        <button
          onClick={handleCompress}
          disabled={files.length === 0 || isProcessing}
          className={cn(
            "w-full bg-accent hover:opacity-90 text-slate-900 py-4 rounded-2xl flex items-center justify-center gap-2 text-sm mt-4 font-black shadow-lg shadow-accent/10 transition-all",
            (files.length === 0 || isProcessing) && "opacity-50 cursor-not-allowed grayscale"
          )}
        >
          {isProcessing ? <Loader2 className="animate-spin" size={18} /> : isDone ? <CheckCircle2 size={18} /> : <Zap size={18} />}
          {isProcessing ? 'OPTIMIZING...' : isDone ? 'DONE!' : 'COMPRESS PDF'}
        </button>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import FileDropzone from '../common/FileDropzone';
import { PDFDocument } from 'pdf-lib';
import { pdfService } from '../../services/pdfService';
import { FileImage, Download, Loader2, CheckCircle2, Archive, Files, Settings } from 'lucide-react';
import { motion } from 'framer-motion';
import { downloadFile } from '../../utils/download';
import JSZip from 'jszip';
import clsx from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs) {
  return twMerge(clsx(inputs));
}

export default function ImageToPDF() {
  const [files, setFiles] = useState([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDone, setIsDone] = useState(false);

  // Options State (iLovePDF Style)
  const [orientation, setOrientation] = useState('portrait');
  const [pageSize, setPageSize] = useState('A4');
  const [margin, setMargin] = useState('none');
  const [mergeAll, setMergeAll] = useState(true);

  const PAGE_SIZES = {
    'A4': { width: 595, height: 842 },
    'Letter': { width: 612, height: 792 },
    'Fit': null
  };

  const MARGINS = {
    'none': 0,
    'small': 20,
    'big': 50
  };

  const handleConvert = async () => {
    if (files.length === 0) return;

    setIsProcessing(true);
    try {
      // Normalize options to service expectations
      const opts = {
        orientation,
        pageSize: pageSize.toLowerCase(), // 'a4'|'letter'|'fit'
        margin: MARGINS[margin] ?? 0
      };

      if (mergeAll) {
        const mergedPdf = await PDFDocument.create();

        for (const file of files) {
          // pdfService.imageToPDF returns bytes for a single-image PDF
          const bytes = await pdfService.imageToPDF(file, opts);
          const single = await PDFDocument.load(bytes);
          const copied = await mergedPdf.copyPages(single, single.getPageIndices());
          copied.forEach(p => mergedPdf.addPage(p));
        }

        const mergedBytes = await mergedPdf.save();
        downloadFile(mergedBytes, `${files[0].name.split('.')[0]}-merged.pdf`);
      } else {
        const zip = new (JSZip.default || JSZip)();
        for (const file of files) {
          const bytes = await pdfService.imageToPDF(file, opts);
          zip.file(`${file.name.split('.')[0]}.pdf`, bytes);
        }
        const content = await zip.generateAsync({ type: 'blob' });
        downloadFile(content, 'Converted-Images-Batch.zip', 'application/zip');
      }

      setIsDone(true);
      setTimeout(() => setIsDone(false), 3000);
    } catch (error) {
      console.error('Conversion failed:', error);
      alert('Failed to convert images to PDF.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 items-start justify-center w-full max-w-6xl">
      <div className="flex-1 w-full">
        <FileDropzone 
          files={files} 
          setFiles={setFiles} 
          multiple={true}
          accept={{ 'image/*': ['.jpg', '.jpeg', '.png'] }} 
        />
      </div>

      <div className="w-full lg:w-80 glass-card p-8 space-y-8 animate-in fade-in slide-in-from-right-4">
        <h3 className="font-bold text-xl text-slate-800 dark:text-zinc-100 flex items-center gap-2">
          <Settings className="text-accent" size={20} />
          Options
        </h3>

        {/* Orientation */}
        <div className="space-y-3">
          <label className="text-sm font-bold text-slate-500 uppercase tracking-wider">Orientation</label>
          <div className="grid grid-cols-2 gap-2">
            {[
              { id: 'portrait', label: 'Portrait', icon: 'Γû»' },
              { id: 'landscape', label: 'Landscape', icon: 'Γû¡' }
            ].map(opt => (
              <button
                key={opt.id}
                onClick={() => setOrientation(opt.id)}
                className={cn(
                  "flex flex-col items-center gap-2 p-4 rounded-2xl border-2 transition-all",
                  orientation === opt.id ? "border-accent bg-accent/5 text-accent" : "border-slate-100 dark:border-zinc-800 text-slate-400 hover:bg-slate-50 dark:hover:bg-zinc-800"
                )}
              >
                <span className="text-2xl leading-none">{opt.icon}</span>
                <span className="text-xs font-bold">{opt.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Page Size */}
        <div className="space-y-3">
          <label className="text-sm font-bold text-slate-500 uppercase tracking-wider">Page Size</label>
          <select 
            value={pageSize}
            onChange={(e) => setPageSize(e.target.value)}
            className="w-full p-4 rounded-2xl border-2 border-slate-100 dark:border-zinc-800 focus:border-accent outline-none font-bold text-slate-700 dark:text-zinc-100 appearance-none bg-slate-50/50 dark:bg-zinc-900/50"
          >
            <option value="A4" className="dark:bg-zinc-900">A4 (297x210 mm)</option>
            <option value="Letter" className="dark:bg-zinc-900">Letter (US)</option>
            <option value="Fit" className="dark:bg-zinc-900">Fit (Same as image)</option>
          </select>
        </div>

        {/* Margin */}
        <div className="space-y-3">
          <label className="text-sm font-bold text-slate-500 uppercase tracking-wider">Margin</label>
          <div className="grid grid-cols-3 gap-2">
            {['none', 'small', 'big'].map(opt => (
              <button
                key={opt}
                onClick={() => setMargin(opt)}
                className={cn(
                  "py-3 rounded-xl border-2 transition-all text-xs font-bold capitalize",
                  margin === opt ? "border-accent bg-accent/5 text-accent" : "border-slate-100 text-slate-400 hover:bg-slate-50"
                )}
              >
                {opt}
              </button>
            ))}
          </div>
        </div>

        {/* Batch Detection / Options */}
        <div className="space-y-4 pt-4 border-t border-slate-100">
          <div className="flex items-center justify-between">
            <label className="text-sm font-bold text-slate-500 uppercase tracking-wider">Conversion Mode</label>
            {files.length > 2 && (
              <span className="bg-yellow-100 text-yellow-700 text-[10px] px-2 py-0.5 rounded-full font-black animate-pulse">
                BATCH DETECTED
              </span>
            )}
          </div>

          <div className="grid grid-cols-1 gap-2">
            <button
              onClick={() => setMergeAll(true)}
              className={cn(
                "w-full p-4 rounded-2xl border-2 transition-all text-left flex items-center gap-3",
                mergeAll ? "border-accent bg-accent/5" : "border-slate-50 dark:border-zinc-800 hover:border-accent/50 hover:bg-accent/5"
              )}
            >
              <div className={cn("p-2 rounded-lg", mergeAll ? "bg-accent text-slate-900" : "bg-slate-100 text-slate-400")}>
                <Files size={18} />
              </div>
              <div>
                <p className={cn("font-bold text-sm", mergeAll ? "text-slate-900 dark:text-zinc-100" : "text-slate-700 dark:text-zinc-300")}>Merge into One PDF</p>
                <p className="text-[10px] text-slate-400 dark:text-zinc-400">All images in a single document</p>
              </div>
            </button>

            <button
              onClick={() => setMergeAll(false)}
              className={cn(
                "w-full p-4 rounded-2xl border-2 transition-all text-left flex items-center gap-3",
                !mergeAll ? "border-accent bg-accent/5" : "border-slate-50 dark:border-zinc-800 hover:border-accent/50 hover:bg-accent/5"
              )}
            >
              <div className={cn("p-2 rounded-lg", !mergeAll ? "bg-accent text-slate-900" : "bg-slate-100 text-slate-400")}>
                <Archive size={18} />
              </div>
              <div>
                <p className={cn("font-bold text-sm", !mergeAll ? "text-slate-900 dark:text-zinc-100" : "text-slate-700 dark:text-zinc-300")}>Individual PDFs (ZIP)</p>
                <p className="text-[10px] text-slate-400 dark:text-zinc-400">Each image becomes its own PDF</p>
              </div>
            </button>
          </div>
        </div>

        <button
          onClick={handleConvert}
          disabled={files.length === 0 || isProcessing}
          className={cn(
            "w-full bg-accent hover:opacity-90 text-slate-900 py-5 rounded-[1.5rem] flex items-center justify-center gap-3 text-lg mt-4 font-black shadow-xl shadow-accent/20 transition-all",
            (files.length === 0 || isProcessing) && "opacity-50 cursor-not-allowed grayscale"
          )}
        >
          {isProcessing ? <Loader2 className="animate-spin" size={24} /> : isDone ? <CheckCircle2 size={24} /> : <Download size={24} />}
          {isProcessing ? 'Converting...' : isDone ? 'Done!' : 'Convert to PDF'}
        </button>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import katex from 'katex';
import 'katex/dist/katex.min.css';
import html2pdf from 'html2pdf.js';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';
import { Sigma, Download, Loader2, CheckCircle2, Settings, Type, FileText, AlignLeft, List, Table } from 'lucide-react';
import clsx from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs) {
  return twMerge(clsx(inputs));
}

const DEFAULT_LATEX = `\\documentclass[12pt]{article}
\\usepackage[a4paper,margin=1in]{geometry}
\\usepackage{amsmath,amssymb,amsthm}
\\usepackage{physics}
\\usepackage{mathtools}
\\usepackage{bm}

\\begin{document}

\\title{Scientific Mathematical Compendium}
\\author{Research Division}
\\date{\\today}

\\maketitle

\\section*{Basic Algebra}
\\[ a+b=c \\]
\\[ x^2 + y^2 = z^2 \\]
\\[ (a+b)^2 = a^2 + 2ab + b^2 \\]
\\[ x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a} \\]
\\[ \\sum_{i=1}^{n} i = \\frac{n(n+1)}{2} \\]

\\section*{Calculus}
\\[ \\lim_{x\\to\\infty}\\frac{1}{x}=0 \\]
\\[ \\frac{d}{dx}(\\sin x)=\\cos x \\]
\\[ \\int_0^1 x^2 \\, dx = \\frac{1}{3} \\]
\\[ \\nabla f(x,y) = \\left( \\frac{\\partial f}{\\partial x}, \\frac{\\partial f}{\\partial y} \\right) \\]

\\section*{Matrices}
\\[ \\begin{bmatrix} 1 & 2 \\\\ 3 & 4 \\end{bmatrix} \\]
\\[ \\det(A)=ad-bc \\]
\\[ \\bm{v}= \\begin{bmatrix} x\\\\ y\\\\ z \\end{bmatrix} \\]

\\section*{Physics & Advanced}
\\[ E=mc^2 \\]
\\[ \\vec{F}=q(\\vec{E}+\\vec{v}\\times\\vec{B}) \\]
\\[ \\nabla \\cdot \\vec{E} = \\frac{\\rho}{\\varepsilon_0} \\]
\\[ \\zeta(s) = \\sum_{n=1}^{\\infty} \\frac{1}{n^s} \\]
\\[ \\boxed{x = \\frac{-b \\pm \\sqrt{b^2-4ac}}{2a}} \\]

\\[ \\left\\{
\\begin{aligned}
2x+y&=5 \\\\
x-y&=1
\\end{aligned}
\\right. \\]

\\section*{Advanced Math \\& Formatting}
% Using the $$ syntax
$$ P(A \\cup B) = P(A) + P(B) - P(A \\cap B) $$

% Standalone Matrix (auto-detected)
\\begin{pmatrix}
\\alpha & \\beta \\\\
\\gamma & \\delta
\\end{pmatrix}

% Piecewise function (cases)
\\begin{cases}
x + y = 5 \\\\
2x - y = 1
\\end{cases}

% Inline math mixed with text
The fundamental theorem of calculus states that if $F(x) = \\int_{a}^{x} f(t) \\, dt$, then $F'(x) = f(x)$.

\\end{document}`;

export default function LaTeXToPDF() {
  const [latex, setLatex] = useState(DEFAULT_LATEX);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDone, setIsDone] = useState(false);
  const [pages, setPages] = useState([]);
  const previewRef = useRef(null);
  const measurerRef = useRef(null);

  const parsedHTML = useMemo(() => {
    let metadata = { title: '', author: '', date: '' };
    let text = latex;

    text = text.replace(/(^|[^\\])%.*$/gm, '$1');

    const bodyMatch = text.match(/\\begin\{document\}([\s\S]*?)\\end\{document\}/);
    if (bodyMatch) {
      text = bodyMatch[1];
    } else {
      text = text.replace(/\\documentclass[\s\S]*?\\begin\{document\}/g, '')
                 .replace(/\\usepackage[\s\S]*?(\n|$)/g, '')
                 .replace(/\\documentclass.*?(\n|$)/g, '');
    }

    const fullText = latex;
    const titleMatch = fullText.match(/\\title\{([\s\S]*?)\}/);
    if (titleMatch) metadata.title = titleMatch[1];

    const authorMatch = fullText.match(/\\author\{([\s\S]*?)\}/);
    if (authorMatch) metadata.author = authorMatch[1];

    const dateMatch = fullText.match(/\\date\{([\s\S]*?)\}/);
    if (dateMatch) {
      const dateVal = dateMatch[1].trim();
      metadata.date = dateVal === '\\today' 
        ? new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }) 
        : dateVal;
    }

    let content = text
      .replace(/\\title\{[\s\S]*?\}/g, '')
      .replace(/\\author\{[\s\S]*?\}/g, '')
      .replace(/\\date\{[\s\S]*?\}/g, '');

    content = content
      .replace(/\\maketitle/g, `
        <div class="text-center mb-12">
          <h1 class="text-3xl font-serif font-bold mb-2" style="color: #0f172a;">${metadata.title}</h1>
          <p class="text-lg font-serif mb-1" style="color: #0f172a;">${metadata.author}</p>
          <p class="text-base font-serif" style="color: #64748b;">${metadata.date}</p>
        </div>
      `)
      .replace(/\\LaTeX\\/g, 'L<sup>a</sup>T<sub>e</sub>X')
      .replace(/\\LaTeX/g, 'L<sup>a</sup>T<sub>e</sub>X')
      .replace(/\\TeX\\/g, 'T<sub>e</sub>X')
      .replace(/\\TeX/g, 'T<sub>e</sub>X')
      .replace(/\\copyright/g, '┬⌐');

    // Handle labels and eqrefs manually to prevent KaTeX errors and support cross-referencing
    let eqCount = 0;
    const labels = {};
    const numberedEnvs = ['equation', 'align', 'gather', 'multline'];
    numberedEnvs.forEach(env => {
      const re = new RegExp('\\\\begin\\{' + env + '\\}([\\s\\S]*?)\\\\end\\{' + env + '\\}', 'g');
      content = content.replace(re, (match, body) => {
        eqCount++;
        const labelMatch = body.match(/\\label\{([^}]+)\}/);
        if (labelMatch) {
          labels[labelMatch[1]] = eqCount;
        }
        const cleanBody = body.replace(/\\label\{[^}]+\}/g, '');
        return `\\begin{${env}}${cleanBody}\\end{${env}}`;
      });
    });

    content = content.replace(/\\eqref\{([^}]+)\}/g, (match, name) => `(${labels[name] || '?'})`);
    content = content.replace(/\\ref\{([^}]+)\}/g, (match, name) => `${labels[name] || '?'}`);
    content = content.replace(/\\begin\{align\*?\}([\s\S]*?)\\end\{align\*?\}/g, (match, body) => {
      try {
        const rendered = katex.renderToString(`\\begin{aligned}${body}\\end{aligned}`, { 
          displayMode: true, 
          throwOnError: false,
          trust: true
        });
        return `<div class="my-10 py-4 math-block flex justify-center" style="line-height: normal; page-break-inside: avoid;">${rendered}</div>`;
      } catch (e) { return match; }
    });

    content = content.replace(/\\begin\{itemize\}(?:\[.*?\])?([\s\S]*?)\\end\{itemize\}/g, (match, body) => {
      const items = body.split('\\item').filter(i => i.trim()).map(i => `<li class="mb-2 pl-2">${i.trim()}</li>`).join('');
      return `<ul class="list-disc ml-8 mb-6 font-serif text-[11pt]">${items}</ul>`;
    });

    content = content.replace(/\\begin\{enumerate\}(?:\[.*?\])?([\s\S]*?)\\end\{enumerate\}/g, (match, body) => {
      const items = body.split('\\item').filter(i => i.trim()).map(i => `<li class="mb-2 pl-2">${i.trim()}</li>`).join('');
      return `<ol class="list-decimal ml-8 mb-6 font-serif text-[11pt]">${items}</ol>`;
    });

    content = content.replace(/\\begin\{multicols\}\{(\d+)\}([\s\S]*?)\\end\{multicols\}/g, (match, cols, body) => {
      return `<div style="column-count: ${cols}; column-gap: 2rem;">${body}</div>`;
    });

    content = content.replace(/\\begin\{tabular\}\{.*?\}[\s\S]*?\\end\{tabular\}/g, (match) => {
      const rows = match.split('\\\\').map(row => {
        const cells = row.replace(/\\begin\{tabular\}\{.*?\}|\\end\{tabular\}|\\hline/g, '').split('&').map(cell => {
          const protectedCell = cell.trim().replace(/\$/g, '<span>$</span>');
          return protectedCell ? `<td class="p-4 text-center" style="border: 1px solid #cbd5e1;">${protectedCell}</td>` : '';
        }).filter(Boolean).join('');
        return cells ? `<tr>${cells}</tr>` : '';
      }).filter(Boolean).join('');
      return `<table class="w-full border-collapse mb-8 font-serif" style="border: 1px solid #cbd5e1; page-break-inside: avoid;">${rows}</table>`;
    });

    // Display math $$ ... $$
    content = content.replace(/(?<!\\)\$\$([\s\S]*?)(?<!\\)\$\$/g, (match, formula) => {
      try {
        return `<div class="my-10 py-4 flex justify-center math-block" style="line-height: normal; page-break-inside: avoid;">${katex.renderToString(formula.trim(), { displayMode: true, throwOnError: false, trust: true })}</div>`;
      } catch (e) { return match; }
    });

    // Display math: \[ ... \], \begin{equation}, align, gather, etc.
    content = content.replace(/\\\[([\s\S]*?)\\\]/g, (match, formula) => {
      try {
        return `<div class="my-10 py-4 flex justify-center math-block" style="line-height: normal; page-break-inside: avoid;">${katex.renderToString(formula.trim(), { displayMode: true, throwOnError: false, trust: true })}</div>`;
      } catch (e) { return match; }
    });

    // Common display environments
    const displayEnvs = ['equation', 'equation\\*', 'align', 'align\\*', 'gather', 'gather\\*', 'multline', 'multline\\*', 'pmatrix', 'bmatrix', 'vmatrix', 'cases', 'split'];
    displayEnvs.forEach(env => {
      const cleanEnv = env.replace('\\\\', '\\');
      const regexEnv = env.replace('\\*', '\\*');
      const re = new RegExp('\\\\begin\\{' + regexEnv + '\\}([\\s\\S]*?)\\\\end\\{' + regexEnv + '\\}', 'g');
      content = content.replace(re, (m, body) => {
        try {
          return `<div class="my-10 py-4 flex justify-center math-block" style="page-break-inside: avoid;">${katex.renderToString(`\\begin{${cleanEnv}}${body.trim()}\\end{${cleanEnv}}`, { displayMode: true, throwOnError: false, trust: true })}</div>`;
        } catch (e) { return m; }
      });
    });

    // Inline math using negative lookbehind to avoid escaped \$
    try {
      content = content.replace(/(?<!\\)\$([\s\S]+?)(?<!\\)\$/g, (match, formula) => {
        if (/^\s*\d+(\.\d+)?\s*$/.test(formula)) return match;
        try {
          return `<span class="inline-math" style="line-height: normal;">${katex.renderToString(formula, { displayMode: false, throwOnError: false, trust: true })}</span>`;
        } catch (e) {
          return match;
        }
      });
    } catch (e) {
      // Some JS environments may not support lookbehind; fallback to safer heuristic
      content = content.replace(/\$([^\$\n]+?)\$/g, (match, formula) => {
        if (/^\s*\d+(\.\d+)?\s*$/.test(formula)) return match;
        try {
          return `<span class="inline-math" style="line-height: normal;">${katex.renderToString(formula, { displayMode: false, throwOnError: false, trust: true })}</span>`;
        } catch (err) { return match; }
      });
    }

    // Inline math using \( ... \)
    content = content.replace(/\\\(([\s\S]+?)\\\)/g, (match, formula) => {
      try {
        return `<span class="inline-math" style="line-height: normal;">${katex.renderToString(formula, { displayMode: false, throwOnError: false, trust: true })}</span>`;
      } catch (err) { return match; }
    });

    // Theorem and Proof environments
    content = content.replace(/\\begin\{proof\}([\s\S]*?)\\end\{proof\}/g, (match, body) => {
      const formattedBody = body.trim().split('\n\n').map(p => `<p class="mb-4 leading-normal text-justify">${p.trim()}</p>`).join('');
      return `<div class="my-6 italic proof-block font-serif text-[11pt]" style="page-break-inside: avoid;"><span class="font-bold italic mr-2">Proof.</span><span class="proof-content">${formattedBody} <span class="float-right text-lg font-normal not-italic mt-[-1.5rem]">Γù╗</span></span></div>`;
    });

    content = content
      .replace(/\\section\*?\{(.*?)\}/g, '<h2 class="text-xl font-serif font-bold mt-8 mb-4 pb-1" style="color: #0f172a; border-bottom: 1px solid #e2e8f0;">$1</h2>')
      .replace(/\\subsection\*?\{(.*?)\}/g, '<h3 class="text-lg font-serif font-bold mt-6 mb-3" style="color: #0f172a;">$1</h3>')
      .replace(/\\textbf\{(.*?)\}/g, '<strong>$1</strong>')
      .replace(/\\textit\{(.*?)\}/g, '<em>$1</em>')
      .replace(/\\underline\{(.*?)\}/g, '<span style="text-decoration: underline;">$1</span>');

    content = content
      .replace(/\\&/g, '&')
      .replace(/\\\$/g, '$')
      .replace(/\\%/g, '%')
      .replace(/\\_/g, '_')
      .replace(/\\\{/g, '{')
      .replace(/\\\}/g, '}');

    content = content
      .replace(/\\Huge/g, '')
      .replace(/\\large/g, '')
      .replace(/\\bfseries/g, '')
      .replace(/\\noindent/g, '')
      .replace(/\\parskip/g, '');

    content = content.replace(/\\newpage/g, `
      <div class="my-12 relative no-print" style="border-top: 2px dashed #f1f5f9;">
        <span class="absolute -top-3 left-1/2 -translate-x-1/2 bg-white px-2 text-[10px] font-bold" style="color: #cbd5e1;">PAGE BREAK</span>
      </div>
      <div class="html2pdf__page-break" style="height: 0; margin: 0; border: none;"></div>
    `);

    content = content.split('\n\n').map(p => {
      // Skip wrapping block elements, but DO wrap inline math (which uses spans)
      if (p.includes('<h') || p.includes('<div') || p.includes('</div') || p.includes('<ul') || p.includes('<ol') || p.includes('<table')) return p;
      const trimmed = p.trim();
      if (!trimmed) return '';

      // Auto-detect unwrapped loose math blocks ONLY if they don't already have rendered KaTeX
      if (!p.includes('class="katex"')) {
        if (/\\frac|\\int|\\sum|\\lim|\\vec|\\sqrt|\\pm|\\infty|\\langle|\\cup|\\cap|\\alpha|\\beta|\\gamma|\\theta|\\pi|\\lambda|\\mu|\\sigma|\\omega|\\nabla|\\partial|\\prod|\\approx|\\neq|\\equiv|\\\\begin\\{/.test(trimmed)) {
          try {
            // Attempt to render the whole paragraph as a display math block
            return `<div class="my-10 py-4 flex justify-center math-block" style="line-height: normal; page-break-inside: avoid;">${katex.renderToString(trimmed.replace(/\n/g, ' '), { displayMode: true, throwOnError: false, trust: true })}</div>`;
          } catch (e) {
            // If it fails, just fall through to normal paragraph
          }
        }
      }

      return `<p class="mb-6 leading-normal font-serif text-[11pt] text-justify">${trimmed.replace(/\n/g, ' ')}</p>`;
    }).join('');

    return content;
  }, [latex]);

  useEffect(() => {
    const paginate = async () => {
      if (!measurerRef.current) return;
      measurerRef.current.innerHTML = parsedHTML;
      const elements = Array.from(measurerRef.current.children);
      const newPages = [];
      let currentPageHTML = '';
      let currentHeight = 0;
      const maxPageHeightPx = (297 - 50) * 3.78; 
      elements.forEach((el) => {
        const elHeight = el.offsetHeight + parseFloat(window.getComputedStyle(el).marginBottom);
        if (currentHeight + elHeight > maxPageHeightPx && currentPageHTML !== '') {
          newPages.push(currentPageHTML);
          currentPageHTML = el.outerHTML;
          currentHeight = elHeight;
        } else {
          currentPageHTML += el.outerHTML;
          currentHeight += elHeight;
        }
      });
      if (currentPageHTML) newPages.push(currentPageHTML);
      setPages(newPages.length > 0 ? newPages : [parsedHTML]);
    };
    paginate();
  }, [parsedHTML]);

  const handleDownload = async () => {
    if (!previewRef.current) return;
    setIsProcessing(true);

    try {
      const pageElements = previewRef.current.querySelectorAll('.page-block');
      if (pageElements.length === 0) return;

      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = pdf.internal.pageSize.getHeight();

      for (let i = 0; i < pageElements.length; i++) {
        const pageEl = pageElements[i];
        if (i > 0) pdf.addPage();

        // 794px x 1123px is the standard A4 @ 96DPI
        const canvas = await html2canvas(pageEl, {
          scale: 2, 
          useCORS: true,
          logging: false,
          backgroundColor: '#ffffff',
          width: 794, 
          height: 1123,
          onclone: (clonedDoc) => {
            const katexElements = clonedDoc.querySelectorAll('.katex');
            katexElements.forEach(el => {
              el.style.lineHeight = '1.2';
              el.style.textRendering = 'optimizeLegibility';
            });

            const allElements = clonedDoc.getElementsByTagName('*');
            for (let j = 0; j < allElements.length; j++) {
              const el = allElements[j];
              const style = window.getComputedStyle(el);
              el.style.fontFamily = '"Times New Roman", Times, serif';

              // Force Consistent Line Spacing
              if (el.tagName === 'P' || el.tagName === 'LI') {
                el.style.lineHeight = '1.5';
                el.style.marginBottom = '1em';
              } else if (el.tagName.startsWith('H')) {
                el.style.lineHeight = '1.2';
              }

              if (style.color.includes('oklch')) el.style.color = '#0f172a';
              if (style.backgroundColor.includes('oklch')) el.style.backgroundColor = 'transparent';
            }
          }
        });

        // Use PNG for lossless line preservation
        const imgData = canvas.toDataURL('image/png');
        pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
      }

      pdf.save('scientific-document.pdf');
      setIsDone(true);
      setTimeout(() => setIsDone(false), 3000);
    } catch (error) {
      console.error('Live capture failed:', error);
      alert('Visual capture failed.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex flex-col xl:flex-row gap-8 items-start justify-center w-full max-w-[1600px] mx-auto px-4">
      <div 
        ref={measurerRef} 
        className="fixed -left-[9999px] top-0 w-[210mm] p-[1in] prose prose-slate invisible no-print"
        style={{ fontFamily: '"Times New Roman", Times, serif' }}
      />
      <div className="w-full xl:w-[450px] space-y-4 shrink-0">
        <div className="glass-card p-6">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-blue-500/10 text-blue-500 rounded-lg flex items-center justify-center">
                <FileText size={18} />
              </div>
              <h4 className="font-black text-xs text-slate-800 dark:text-zinc-100 uppercase tracking-widest">Document Editor</h4>
            </div>
          </div>
          <textarea
            value={latex}
            onChange={(e) => setLatex(e.target.value)}
            className="w-full h-[700px] p-6 bg-slate-50/50 dark:bg-zinc-900/50 rounded-2xl border-2 border-transparent focus:border-accent outline-none font-mono text-xs leading-loose text-slate-700 dark:text-zinc-300 transition-all scrollbar-hide"
            placeholder="Write your LaTeX here..."
          />
          <div className="mt-6 flex flex-wrap gap-2">
            <div className="flex items-center gap-1 text-[9px] font-black text-slate-400 bg-slate-50 dark:bg-zinc-900/50 px-2 py-1 rounded-md uppercase">
              <AlignLeft size={10} /> Align
            </div>
            <div className="flex items-center gap-1 text-[9px] font-black text-slate-400 bg-slate-50 dark:bg-zinc-900/50 px-2 py-1 rounded-md uppercase">
              <List size={10} /> Lists
            </div>
            <div className="flex items-center gap-1 text-[9px] font-black text-slate-400 bg-slate-50 dark:bg-zinc-900/50 px-2 py-1 rounded-md uppercase">
              <Table size={10} /> Tables
            </div>
          </div>
        </div>
      </div>
      <div className="flex-1 w-full flex flex-col items-center">
        <div className="w-full flex items-center justify-between mb-4 px-2">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-accent/20 flex items-center justify-center">
              <FileText className="text-accent" size={18} />
            </div>
            <div>
              <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-widest">PAGINATED PREVIEW</h3>
              <p className="text-[10px] text-slate-400 dark:text-zinc-400 font-bold uppercase tracking-tighter">Smart A4 Physical Layout</p>
            </div>
          </div>
          <button
            onClick={handleDownload}
            disabled={isProcessing}
            className={cn("btn-primary flex items-center gap-2 text-xs py-2.5", isProcessing && "opacity-50 cursor-not-allowed")}
          >
            {isProcessing ? <Loader2 className="animate-spin" size={16} /> : isDone ? <CheckCircle2 size={16} /> : <Download size={16} />}
            {isProcessing ? 'EXPORTING...' : isDone ? 'EXPORTED!' : 'DOWNLOAD PDF'}
          </button>
        </div>
        <div className="w-full overflow-x-auto pb-24 scrollbar-hide">
          <div 
            ref={previewRef}
            className="flex flex-col items-center gap-12 pages-container"
          >
            {pages.map((pageHTML, index) => (
              <div 
                key={index}
                className="bg-white text-[#0f172a] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.2)] w-[210mm] min-h-[297mm] p-[1in] box-border relative page-block"
                style={{ fontFamily: '"Times New Roman", Times, serif' }}
              >
                <div className="absolute top-4 right-8 text-[9px] font-black text-slate-300 dark:text-zinc-500 uppercase tracking-widest no-print">
                  Page {index + 1}
                </div>
                <div 
                  className="prose prose-slate max-w-none prose-headings:font-serif prose-p:font-serif"
                  dangerouslySetInnerHTML={{ __html: pageHTML }} 
                />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import FileDropzone from '../common/FileDropzone';
import { pdfService } from '../../services/pdfService';
import { Merge, Download, Loader2, CheckCircle2, GripVertical, File, X, Settings } from 'lucide-react';
import { motion, Reorder } from 'framer-motion';
import { downloadFile } from '../../utils/download';
import clsx from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs) {
  return twMerge(clsx(inputs));
}

export default function MergePDF() {
  const [files, setFiles] = useState([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDone, setIsDone] = useState(false);

  const handleMerge = async () => {
    if (files.length < 2) return;

    setIsProcessing(true);
    try {
      const mergedPdfBytes = await pdfService.mergePDFs(files);
      downloadFile(mergedPdfBytes, `merged-${files[0].name}`);
      setIsDone(true);
      setTimeout(() => setIsDone(false), 3000);
    } catch (error) {
      console.error('Merge failed:', error);
      alert('Failed to merge PDFs. Please try again.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 items-start justify-center w-full max-w-6xl">
      <div className="flex-1 w-full space-y-6">
        <FileDropzone files={files} setFiles={setFiles} hideFileList={true} multiple={true} />

        {files.length > 0 && (
          <div className="w-full">
            <h4 className="text-xs font-black text-slate-400 mb-4 uppercase tracking-[0.2em]">Drag to reorder pages</h4>
            <Reorder.Group 
              axis="y" 
              values={files} 
              onReorder={setFiles}
              className="space-y-2"
            >
              {files.map((file, index) => (
                <Reorder.Item 
                  key={`${file.name}-${index}`} 
                  value={file}
                  className="glass-card p-4 flex items-center gap-4 cursor-grab active:cursor-grabbing group"
                >
                  <div className="text-slate-300 group-hover:text-accent transition-colors">
                    <GripVertical size={20} />
                  </div>
                  <div className="w-10 h-10 bg-slate-50 dark:bg-zinc-800/50 text-slate-400 rounded-xl flex items-center justify-center">
                    <File size={20} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-bold text-slate-800 dark:text-zinc-100 truncate">{file.name}</p>
                    <p className="text-[10px] text-slate-400 font-medium">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                  </div>
                  <button 
                    onClick={() => setFiles(files.filter((_, i) => i !== index))}
                    className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all"
                  >
                    <X size={18} />
                  </button>
                </Reorder.Item>
              ))}
            </Reorder.Group>
          </div>
        )}
      </div>

      <div className="w-full lg:w-72 glass-card p-6 space-y-6 animate-in fade-in slide-in-from-right-4">
        <div className="flex items-center justify-between">
          <h3 className="font-black text-lg text-slate-800 dark:text-zinc-100 flex items-center gap-2">
            <Settings className="text-accent" size={18} />
            SETTINGS
          </h3>
          {files.length > 2 && (
            <span className="bg-yellow-100 text-yellow-700 text-[8px] px-2 py-0.5 rounded-full font-black">
              BATCH
            </span>
          )}
        </div>

        <div className="space-y-3">
          <p className="text-[11px] text-slate-400 font-medium leading-relaxed uppercase tracking-wider">
            {files.length < 2 
              ? 'Add at least 2 PDF files to combine them into one single document.'
              : `Combine ${files.length} PDFs into one.`}
          </p>
        </div>

        <button
          onClick={handleMerge}
          disabled={files.length < 2 || isProcessing}
          className={cn(
            "w-full bg-accent hover:opacity-90 text-slate-900 py-4 rounded-2xl flex items-center justify-center gap-2 text-sm mt-4 font-black shadow-lg shadow-accent/10 transition-all",
            (files.length < 2 || isProcessing) && "opacity-50 cursor-not-allowed grayscale"
          )}
        >
          {isProcessing ? <Loader2 className="animate-spin" size={18} /> : isDone ? <CheckCircle2 size={18} /> : <Merge size={18} />}
          {isProcessing ? 'MERGING...' : isDone ? 'DONE!' : 'MERGE PDF'}
        </button>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import FileDropzone from '../common/FileDropzone';
import { ocrService } from '../../services/ocrService';
import { jsPDF } from 'jspdf';
import { PDFDocument } from 'pdf-lib';
import { FileSearch, Copy, Download, Loader2, CheckCircle2, Archive, FileText, Settings } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { downloadFile } from '../../utils/download';
import JSZip from 'jszip';
import clsx from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs) {
  return twMerge(clsx(inputs));
}

export default function OCRTool() {
  const [files, setFiles] = useState([]);
  const [resultText, setResultText] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [progress, setProgress] = useState('');

  const handleOCR = async () => {
    if (files.length === 0) return;

    setIsProcessing(true);
    setResultText('');
    try {
      const zip = new (JSZip.default || JSZip)();
      let totalText = '';
      let successCount = 0;
      const failedFiles = [];

      for (let fileIdx = 0; fileIdx < files.length; fileIdx++) {
        const file = files[fileIdx];
        setProgress(`Processing ${file.name}...`);
        try {
          if (file.type === 'application/pdf') {
            const pdfBytes = await file.arrayBuffer();
            const pdfDoc = await PDFDocument.load(pdfBytes);
            const pageCount = pdfDoc.getPageCount();

            let docText = '';
            for (let i = 1; i <= pageCount; i++) {
              setProgress(`Scanning ${file.name} - Page ${i}/${pageCount}...`);
              const imageBlob = await ocrService.pdfPageToImage(file, i);
              const text = await ocrService.recognizeText(imageBlob);
              docText += `--- Page ${i} ---\n\n${text}\n\n`;
            }

            if (files.length === 1) {
              totalText = docText;
            } else {
              zip.file(`OCR-${file.name.split('.')[0]}.txt`, docText);
            }
          } else {
            const text = await ocrService.recognizeText(file);
            if (files.length === 1) {
              totalText = text;
            } else {
              zip.file(`OCR-${file.name.split('.')[0]}.txt`, text);
            }
          }

          successCount++;
        } catch (fileError) {
          console.error(`Failed processing ${file.name}:`, fileError);
          failedFiles.push({ name: file.name, error: fileError.message || String(fileError) });
        }
      }

      // Finalize results and provide user feedback
      if (files.length === 1) {
        if (successCount === 1) {
          setResultText(totalText);
          downloadFile(totalText, `OCR-${files[0].name.split('.')[0]}.txt`, 'text/plain');
        } else {
          throw new Error(`Failed to process file: ${files[0].name}`);
        }
      } else {
        if (successCount > 0) {
          const content = await zip.generateAsync({ type: 'blob' });
          downloadFile(content, 'OCR-Batch.zip', 'application/zip');
          setResultText(`Batch processing complete: ${successCount} succeeded, ${failedFiles.length} failed.`);
        } else {
          throw new Error('All files failed during OCR processing.');
        }
      }

      if (failedFiles.length > 0) {
        // Show a concise error summary
        const summary = failedFiles.map(f => `${f.name}: ${f.error}`).join('\n');
        alert(`Some files failed during OCR:\n${summary}`);
      }
    } catch (error) {
      console.error('OCR failed:', error);
      alert('Failed to extract text. Make sure the file is clear and readable.');
    } finally {
      setIsProcessing(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(resultText);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const downloadText = () => {
    downloadFile(resultText, `text-${files[0].name.split('.')[0]}.txt`, 'text/plain');
  };

  const downloadAsPDF = () => {
    const doc = new jsPDF();
    const splitText = doc.splitTextToSize(resultText, 180);
    doc.text(splitText, 15, 20);
    doc.save(`OCR-${files[0].name.split('.')[0]}.pdf`);
  };

  return (
    <div className="w-full flex flex-col items-center">
      <div className="flex flex-col lg:flex-row gap-8 items-start justify-center w-full max-w-6xl">
        <div className="flex-1 w-full">
          <FileDropzone 
            files={files} 
            setFiles={setFiles} 
            multiple={true}
            accept={{ 
              'image/*': ['.jpg', '.jpeg', '.png'],
              'application/pdf': ['.pdf']
            }} 
          />
        </div>

        <div className="w-full lg:w-72 glass-card p-6 space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="font-black text-xs text-slate-800 dark:text-slate-100 flex items-center gap-2 uppercase tracking-widest">
              <Settings className="text-accent" size={16} />
              Parameters
            </h3>
            {files.length > 2 && (
              <span className="bg-accent/20 text-accent text-[8px] px-2 py-0.5 rounded-full font-black">
                BATCH
              </span>
            )}
          </div>

          <div className="space-y-3">
            <p className="text-[10px] text-slate-400 dark:text-slate-500 font-bold leading-relaxed uppercase tracking-widest">
              {files.length > 1 
                ? `Scanning ${files.length} documents for text extraction.`
                : 'Intelligent character recognition system ready.'}
            </p>
          </div>

          <button
            onClick={handleOCR}
            disabled={files.length === 0 || isProcessing}
            className={cn(
              "btn-primary w-full flex items-center justify-center gap-3 text-xs",
              (files.length === 0 || isProcessing) && "opacity-50 cursor-not-allowed grayscale"
            )}
          >
            {isProcessing ? <Loader2 className="animate-spin" size={16} /> : <FileSearch size={16} />}
            {isProcessing ? 'SCANNING...' : 'EXTRACT TEXT'}
          </button>

          {progress && (
            <p className="text-[10px] text-accent font-black text-center animate-pulse uppercase tracking-widest">
              {progress}
            </p>
          )}
        </div>
      </div>

      <AnimatePresence>
        {resultText && (
          <motion.div 
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 30 }}
            className="mt-12 w-full max-w-4xl glass-card p-8"
          >
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
              <div>
                <h4 className="text-2xl font-black text-slate-900 dark:text-white tracking-tighter">EXTRACTED CONTENT</h4>
                <p className="text-[10px] text-slate-400 font-black mt-1 uppercase tracking-widest">Digital Text Output Stream</p>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={copyToClipboard}
                  className="btn-secondary px-6 py-3 flex items-center gap-2 text-xs font-bold"
                >
                  {isCopied ? <CheckCircle2 size={18} className="text-accent" /> : <Copy size={18} />}
                  {isCopied ? 'COPIED!' : 'COPY'}
                </button>
                <button 
                  onClick={downloadText}
                  className="btn-secondary px-4 py-3 flex items-center gap-2 text-[10px] font-black"
                >
                  <Download size={14} />
                  TXT
                </button>
                <button 
                  onClick={downloadAsPDF}
                  className="btn-secondary px-4 py-3 flex items-center gap-2 text-[10px] font-black"
                >
                  <FileText size={14} />
                  PDF
                </button>
              </div>
            </div>
            <div className="bg-slate-50/50 dark:bg-zinc-900/50 p-8 rounded-[2rem] border border-slate-100 dark:border-white/5 min-h-[300px] max-h-[600px] overflow-y-auto whitespace-pre-wrap text-slate-700 dark:text-zinc-300 font-mono text-sm leading-relaxed scrollbar-hide shadow-inner">
              {resultText}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

